\begin{remark}[curvature derivative identity at the initial point]
  \label{rem:dc-ch5-2-8}
  \dcref{ch5:2.8}
  Identity (4) also follows by covariantly differentiating the curvature
  tensor along $\gamma$ and using $J(0)=0$.
\end{remark}

